const styles = await page.evaluate(() => {
  const rootStyles = getComputedStyle(document.documentElement);
  const body = document.body;
  const bodyStyles = getComputedStyle(body);

  const nav = document.querySelector('nav, header, [class*="navbar"], [class*="header"]');
  const navStyles = nav ? getComputedStyle(nav) : null;

  const cta = document.querySelector('a[href*="inscricao"], button, [class*="btn"], [class*="button"]');
  const ctaStyles = cta ? getComputedStyle(cta) : null;

  const h1 = document.querySelector('h1');
  const h2 = document.querySelector('h2');
  const p = document.querySelector('p');

  // Cores extraídas de elementos
  const allElements = Array.from(document.querySelectorAll('*'));
  const colors = new Set();
  const bgColors = new Set();
  allElements.slice(0, 100).forEach(el => {
    const s = getComputedStyle(el);
    if (s.color && s.color !== 'rgba(0, 0, 0, 0)') colors.add(s.color);
    if (s.backgroundColor && s.backgroundColor !== 'rgba(0, 0, 0, 0)') bgColors.add(s.backgroundColor);
  });

  return {
    body: {
      backgroundColor: bodyStyles.backgroundColor,
      color: bodyStyles.color,
      fontFamily: bodyStyles.fontFamily,
      fontSize: bodyStyles.fontSize
    },
    nav: navStyles ? {
      backgroundColor: navStyles.backgroundColor,
      color: navStyles.color,
      fontFamily: navStyles.fontFamily
    } : null,
    cta: ctaStyles ? {
      backgroundColor: ctaStyles.backgroundColor,
      color: ctaStyles.color,
      borderRadius: ctaStyles.borderRadius,
      fontFamily: ctaStyles.fontFamily,
      fontWeight: ctaStyles.fontWeight,
      padding: ctaStyles.padding,
      textTransform: ctaStyles.textTransform
    } : null,
    h1: h1 ? {
      fontFamily: getComputedStyle(h1).fontFamily,
      fontSize: getComputedStyle(h1).fontSize,
      fontWeight: getComputedStyle(h1).fontWeight,
      color: getComputedStyle(h1).color,
      letterSpacing: getComputedStyle(h1).letterSpacing
    } : null,
    h2: h2 ? {
      fontFamily: getComputedStyle(h2).fontFamily,
      fontSize: getComputedStyle(h2).fontSize,
      fontWeight: getComputedStyle(h2).fontWeight,
      color: getComputedStyle(h2).color
    } : null,
    uniqueTextColors: Array.from(colors).slice(0, 15),
    uniqueBgColors: Array.from(bgColors).slice(0, 15)
  };
});
return JSON.stringify(styles, null, 2);

// Scroll para capturar seções com fundos coloridos
await page.evaluate(() => window.scrollTo(0, document.body.scrollHeight * 0.3));
await page.waitForTimeout(800);

const result = await page.evaluate(() => {
  const sections = Array.from(document.querySelectorAll('section, div[class*="section"], div[class*="hero"], div[class*="banner"], header, footer'));
  const samples = sections.slice(0, 15).map(el => {
    const s = getComputedStyle(el);
    return {
      tag: el.tagName,
      class: el.className?.toString?.().slice(0, 60),
      bg: s.backgroundColor,
      color: s.color,
      fontFamily: s.fontFamily
    };
  });

  // Buscar todos os bg colors únicos na página inteira
  const allBg = new Set();
  document.querySelectorAll('*').forEach(el => {
    const s = getComputedStyle(el);
    if (s.backgroundColor && s.backgroundColor !== 'rgba(0, 0, 0, 0)' && s.backgroundColor !== 'rgb(255, 255, 255)') {
      allBg.add(s.backgroundColor);
    }
  });

  // Buscar botões reais
  const buttons = Array.from(document.querySelectorAll('a[class*="btn"], a[class*="button"], a[href*="inscricao"], a[href*="Saiba"], a[href*="Explorar"]'));
  const btnSamples = buttons.slice(0, 5).map(btn => {
    const s = getComputedStyle(btn);
    return {
      text: btn.textContent?.slice(0, 30),
      bg: s.backgroundColor,
      color: s.color,
      radius: s.borderRadius,
      weight: s.fontWeight,
      padding: s.padding,
      border: s.border
    };
  });

  return {
    sections: samples,
    uniqueNonWhiteBgColors: Array.from(allBg).slice(0, 20),
    buttons: btnSamples
  };
});
return JSON.stringify(result, null, 2);

