def score_band(score: float) -> str:
    """Retorna classe CSS para o badge de score (cores wash)."""
    if score >= 80:
        return "score-high"
    if score >= 50:
        return "score-mid"
    return "score-low"


def score_label(score: float) -> str:
    if score >= 80:
        return "Quente"
    if score >= 50:
        return "Morno"
    return "Frio"


def fmt_brl(value: float) -> str:
    return f"R$ {value:,.0f}".replace(",", ".")


def render_kpi(label: str, value: str) -> None:
    st.markdown(
