DATA_DIR = BASE / "data"
PIPELINE_CSV = DATA_DIR / "sales_pipeline.csv"
ACCOUNTS_CSV = DATA_DIR / "accounts.csv"
PRODUCTS_CSV = DATA_DIR / "products.csv"
