    with cols[2]:
        render_kpi("Valor em jogo", fmt_brl(total_value), compact=True)
    with cols[3]:
        render_kpi("Top deal", top_deal_label, compact=True)

    st.markdown("")  # spacer

    # --- Top N deals prioritários ---
