                    """,
                    unsafe_allow_html=True,
                )
            st.markdown("")  # spacer entre cards

    render_followup_assistant(filtered)

    # --- Tabela completa expandida ---
    st.markdown("---")
    st.markdown("### Pipeline completo (filtrado)")
    table_cols = [
        "opportunity_id", "sales_agent", "manager", "regional_office",
